const input = $json;

const message =
  input.chatInput ??
  input.message ??
  input.text ??
  "";

const sessionId =
  input.sessionId ??
  input.session_id ??
  `session-${Date.now()}`;

if (!message || !String(message).trim()) {
  throw new Error("Le message de l'étudiant est vide.");
}

return {
  session_id: String(sessionId),
  user_id: String(input.userId ?? input.user_id ?? sessionId),
  language: String(input.language ?? "fr"),
  message: String(message).trim(),
  received_at: new Date().toISOString()
};

const request = $('Préparer la requête').first().json;
const storedRow = $input.first()?.json ?? {};

function parseJson(value, fallback) {
  if (value === null || value === undefined || value === '') {
    return fallback;
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

const defaultProfile = {
  bac_type: null,
  score: null,
  score_fg: null,
  annee_bac: 2026,
  gouvernorat_residence: null,
  regions_preferees: [],
  domaines_preferes: [],
  matieres_preferees: [],
  matieres_a_eviter: [],
  types_etablissement: [],
  mobilite_nationale: null,
  internat_requis: null,
  objectifs_professionnels: [],
  contraintes: [],
  langue_preferee: request.language
};

const studentProfile = parseJson(
  storedRow.student_profile,
  defaultProfile
);

const searchResults = parseJson(
  storedRow.search_results,
  {
    status: 'not_started',
    recommended_programs: [],
    excluded_programs: []
  }
);

const comparisonResults = parseJson(
  storedRow.comparison_results,
  {
    status: 'not_started',
    final_recommendations: []
  }
);

return [
  {
    json: {
      memory_exists: Boolean(storedRow.session_id),
      memory_row_id: storedRow.id ?? null,

      session_id: request.session_id,
      user_id: request.user_id,
      language: request.language,
      current_message: request.message,

      current_stage: storedRow.current_stage ?? 'profiling',

      student_profile: studentProfile,
      search_results: searchResults,
      comparison_results: comparisonResults,

      updated_at: new Date().toISOString()
    }
  }
];

const state = $json;

const systemPrompt = `
Tu es l'Agent 1 de profilage d'un assistant d'orientation universitaire tunisienne.

MISSION
Tu dois extraire les informations du nouveau message et les fusionner avec le profil actuel.

Tu ne dois pas :
- rechercher des formations ;
- recommander des établissements ;
- inventer des valeurs ;
- supprimer une ancienne information si le nouveau message ne la modifie pas ;
- écrire du texte en dehors du JSON.

INFORMATIONS ESSENTIELLES
- bac_type ;
- score ou score_fg ;
- domaines_preferes ;
- regions_preferees ou mobilite_nationale.

INFORMATIONS FACULTATIVES
- gouvernorat_residence ;
- matieres_preferees ;
- matieres_a_eviter ;
- types_etablissement ;
- internat_requis ;
- objectifs_professionnels ;
- contraintes.

REGLES
1. Fusionne le nouveau message avec le profil actuel.
2. Si l'étudiant change une information, utilise la nouvelle valeur.
3. Une information inconnue doit rester null ou [].
4. Toutes les listes doivent être des tableaux JSON.
5. Pose au maximum trois questions.
6. Utilise la langue indiquée.
7. Retourne uniquement un objet JSON valide.
8. N'utilise pas de bloc Markdown.

FORMAT EXACT
{
  "status": "complete ou incomplete",
  "profile_changed": true,
  "changed_fields": [],
  "missing_fields": [],
  "student_profile": {
    "bac_type": null,
    "score": null,
    "score_fg": null,
    "annee_bac": 2026,
    "gouvernorat_residence": null,
    "regions_preferees": [],
    "domaines_preferes": [],
    "matieres_preferees": [],
    "matieres_a_eviter": [],
    "types_etablissement": [],
    "mobilite_nationale": null,
    "internat_requis": null,
    "objectifs_professionnels": [],
    "contraintes": [],
    "langue_preferee": null
  },
  "profile_summary": "",
  "next_questions": []
}
`;

const userPrompt = `
LANGUE DE L'ETUDIANT
${state.language}

PROFIL ACTUEL
${JSON.stringify(state.student_profile, null, 2)}

NOUVEAU MESSAGE
${state.current_message}

Mets le profil à jour et retourne uniquement le JSON demandé.
`;

return {
  ...state,

  openwebui_body: {
    model: "gemma4:e4b",
    stream: false,
    temperature: 0.1,
    messages: [
      {
        role: "system",
        content: systemPrompt.trim()
      },
      {
        role: "user",
        content: userPrompt.trim()
      }
    ]
  }
};

/*
 * N8N CODE NODE
 * Nom : Parser Agent 1
 * Mode : Run Once for Each Item
 *
 * Entrée :
 * Réponse du nœud HTTP Request "Open WebUI - Agent 1"
 *
 * Sortie :
 * État complet de la session avec :
 * - student_profile
 * - profile_complete
 * - missing_fields
 * - next_questions
 * - mémoire de recherche et comparaison réinitialisée si nécessaire
 */

// ============================================================
// 1. Récupérer la réponse Open WebUI et l'état précédent
// ============================================================

const response = $json;

const state = $('Préparer Agent 1 - Profilage').item.json;


// ============================================================
// 2. Chercher le contenu produit par le modèle
// ============================================================

// Le premier chemin correspond au format OpenAI/Open WebUI standard.
// Les chemins supplémentaires rendent le parser compatible avec
// plusieurs variantes de réponses.
let content =
  response.choices?.[0]?.message?.content ??
  response.choices?.[0]?.text ??
  response.message?.content ??
  response.response ??
  response.content ??
  response.text ??
  response.data?.choices?.[0]?.message?.content ??
  response.body?.choices?.[0]?.message?.content ??
  null;

if (content === null || content === undefined || content === '') {
  throw new Error(
    "Open WebUI n'a retourné aucun contenu exploitable pour l'Agent 1.\n" +
    "Réponse complète reçue :\n" +
    JSON.stringify(response, null, 2)
  );
}


// ============================================================
// 3. Convertir le contenu en texte si nécessaire
// ============================================================

if (typeof content === 'object') {
  content = JSON.stringify(content);
}

content = String(content).trim();


// ============================================================
// 4. Nettoyer les blocs Markdown éventuels
// ============================================================

function removeMarkdownCodeBlock(text) {
  return String(text)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```javascript\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}


// ============================================================
// 5. Extraire le premier objet JSON équilibré
// ============================================================

function findFirstCompleteJsonObject(text) {
  const source = String(text);

  let startIndex = -1;
  let depth = 0;
  let insideString = false;
  let escaped = false;

  for (let index = 0; index < source.length; index++) {
    const character = source[index];

    if (startIndex === -1) {
      if (character === '{') {
        startIndex = index;
        depth = 1;
      }

      continue;
    }

    if (insideString) {
      if (escaped) {
        escaped = false;
        continue;
      }

      if (character === '\\') {
        escaped = true;
        continue;
      }

      if (character === '"') {
        insideString = false;
      }

      continue;
    }

    if (character === '"') {
      insideString = true;
      continue;
    }

    if (character === '{') {
      depth++;
      continue;
    }

    if (character === '}') {
      depth--;

      if (depth === 0) {
        return source.slice(startIndex, index + 1);
      }
    }
  }

  return null;
}


// ============================================================
// 6. Réparer quelques erreurs JSON fréquentes des modèles locaux
// ============================================================

function repairCommonJsonErrors(text) {
  return String(text)
    // Supprimer les virgules avant une fermeture d'objet ou de tableau.
    .replace(/,\s*}/g, '}')
    .replace(/,\s*]/g, ']')

    // Remplacer les valeurs Python fréquentes hors chaînes.
    .replace(/:\s*None(?=\s*[,}])/g, ': null')
    .replace(/:\s*True(?=\s*[,}])/g, ': true')
    .replace(/:\s*False(?=\s*[,}])/g, ': false')

    // Supprimer les caractères invisibles problématiques.
    .replace(/^\uFEFF/, '')
    .trim();
}


// ============================================================
// 7. Parser proprement le JSON Agent 1
// ============================================================

function parseAgentJson(rawContent) {
  const cleaned = removeMarkdownCodeBlock(rawContent);

  // Première tentative : tout le contenu est déjà un JSON valide.
  try {
    const parsed = JSON.parse(cleaned);

    // Certains modèles retournent un JSON encodé dans une chaîne.
    if (typeof parsed === 'string') {
      return JSON.parse(removeMarkdownCodeBlock(parsed));
    }

    return parsed;
  } catch (firstError) {
    // Continuer vers l'extraction de l'objet JSON.
  }

  const extracted = findFirstCompleteJsonObject(cleaned);

  if (!extracted) {
    throw new Error(
      "Aucun objet JSON complet n'a été trouvé dans la réponse de l'Agent 1.\n" +
      "Contenu reçu :\n" +
      cleaned
    );
  }

  // Deuxième tentative : parser uniquement l'objet extrait.
  try {
    return JSON.parse(extracted);
  } catch (secondError) {
    // Continuer vers une réparation minimale.
  }

  const repaired = repairCommonJsonErrors(extracted);

  try {
    return JSON.parse(repaired);
  } catch (thirdError) {
    throw new Error(
      "Le JSON retourné par l'Agent 1 est invalide.\n" +
      "Erreur JSON : " +
      thirdError.message +
      "\n\nJSON extrait :\n" +
      extracted +
      "\n\nJSON après réparation :\n" +
      repaired
    );
  }
}

const result = parseAgentJson(content);


// ============================================================
// 8. Vérifier que la racine est un objet JSON
// ============================================================

if (
  !result ||
  typeof result !== 'object' ||
  Array.isArray(result)
) {
  throw new Error(
    "La réponse de l'Agent 1 doit être un objet JSON et non un tableau ou un texte.\n" +
    "Valeur reçue :\n" +
    JSON.stringify(result, null, 2)
  );
}


// ============================================================
// 9. Fonctions de normalisation
// ============================================================

function ensureArray(value) {
  if (Array.isArray(value)) {
    return value
      .map(item => {
        if (typeof item === 'string') {
          return item.trim();
        }

        return item;
      })
      .filter(item => {
        if (item === null || item === undefined || item === '') {
          return false;
        }

        return true;
      });
  }

  if (value === null || value === undefined || value === '') {
    return [];
  }

  if (typeof value === 'string') {
    const cleanedValue = value.trim();

    if (!cleanedValue) {
      return [];
    }

    return cleanedValue
      .split(/[,;|]/)
      .map(item => item.trim())
      .filter(Boolean);
  }

  return [value];
}

function ensureNullableString(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const stringValue = String(value).trim();

  return stringValue || null;
}

function ensureNullableBoolean(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  if (typeof value === 'boolean') {
    return value;
  }

  const normalized = String(value).trim().toLowerCase();

  if (
    normalized === 'true' ||
    normalized === 'oui' ||
    normalized === 'yes' ||
    normalized === '1'
  ) {
    return true;
  }

  if (
    normalized === 'false' ||
    normalized === 'non' ||
    normalized === 'no' ||
    normalized === '0'
  ) {
    return false;
  }

  return null;
}

function ensureNullableNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }

  let normalized = String(value)
    .trim()
    .replace(/\s/g, '')
    .replace(',', '.');

  // Extraire un nombre si le modèle retourne par exemple "142 points".
  const match = normalized.match(/-?\d+(?:\.\d+)?/);

  if (!match) {
    return null;
  }

  const numberValue = Number(match[0]);

  return Number.isFinite(numberValue)
    ? numberValue
    : null;
}

function normalizeTextList(value) {
  return ensureArray(value)
    .map(item => String(item).trim())
    .filter(Boolean);
}


// ============================================================
// 10. Récupérer et normaliser le profil
// ============================================================

if (
  !result.student_profile ||
  typeof result.student_profile !== 'object' ||
  Array.isArray(result.student_profile)
) {
  throw new Error(
    "Le champ student_profile est absent ou invalide dans la réponse de l'Agent 1.\n" +
    "Réponse parsée :\n" +
    JSON.stringify(result, null, 2)
  );
}

const rawProfile = result.student_profile;

const previousProfile =
  state.student_profile &&
  typeof state.student_profile === 'object'
    ? state.student_profile
    : {};

// Fusionner le profil précédent et le nouveau profil.
// Les anciennes propriétés non renvoyées par le modèle sont conservées.
const mergedProfile = {
  ...previousProfile,
  ...rawProfile
};

const studentProfile = {
  bac_type: ensureNullableString(
    mergedProfile.bac_type
  ),

  score: ensureNullableNumber(
    mergedProfile.score
  ),

  score_fg: ensureNullableNumber(
    mergedProfile.score_fg
  ),

  annee_bac:
    ensureNullableNumber(mergedProfile.annee_bac) ??
    ensureNullableNumber(previousProfile.annee_bac) ??
    2026,

  gouvernorat_residence: ensureNullableString(
    mergedProfile.gouvernorat_residence ??
    mergedProfile.gouvernorat
  ),

  regions_preferees: normalizeTextList(
    mergedProfile.regions_preferees
  ),

  domaines_preferes: normalizeTextList(
    mergedProfile.domaines_preferes
  ),

  matieres_preferees: normalizeTextList(
    mergedProfile.matieres_preferees
  ),

  matieres_a_eviter: normalizeTextList(
    mergedProfile.matieres_a_eviter
  ),

  types_etablissement: normalizeTextList(
    mergedProfile.types_etablissement ??
    mergedProfile.type_etablissement
  ),

  mobilite_nationale: ensureNullableBoolean(
    mergedProfile.mobilite_nationale ??
    mergedProfile.mobilite
  ),

  internat_requis: ensureNullableBoolean(
    mergedProfile.internat_requis
  ),

  objectifs_professionnels: normalizeTextList(
    mergedProfile.objectifs_professionnels
  ),

  contraintes: normalizeTextList(
    mergedProfile.contraintes
  ),

  langue_preferee:
    ensureNullableString(
      mergedProfile.langue_preferee
    ) ??
    ensureNullableString(state.language) ??
    'fr'
};

// Conserver des champs personnalisés éventuels renvoyés par le modèle.
const normalizedStudentProfile = {
  ...mergedProfile,
  ...studentProfile
};


// ============================================================
// 11. Normaliser les métadonnées Agent 1
// ============================================================

const changedFields = normalizeTextList(
  result.changed_fields
);

const missingFieldsFromAgent = normalizeTextList(
  result.missing_fields
);

const nextQuestions = normalizeTextList(
  result.next_questions
);

const agentStatus = String(
  result.status ?? ''
).trim().toLowerCase();

const profileChanged =
  typeof result.profile_changed === 'boolean'
    ? result.profile_changed
    : changedFields.length > 0;


// ============================================================
// 12. Vérification déterministe des champs essentiels
// ============================================================

// Le profil est considéré comme complet si :
// - le type de bac est présent ;
// - score ou score_fg est présent ;
// - au moins un domaine est présent ;
// - au moins une région est présente,
//   OU la mobilité nationale est explicitement true.

const deterministicMissingFields = [];

if (!normalizedStudentProfile.bac_type) {
  deterministicMissingFields.push('bac_type');
}

if (
  normalizedStudentProfile.score === null &&
  normalizedStudentProfile.score_fg === null
) {
  deterministicMissingFields.push('score');
}

if (
  !Array.isArray(normalizedStudentProfile.domaines_preferes) ||
  normalizedStudentProfile.domaines_preferes.length === 0
) {
  deterministicMissingFields.push('domaines_preferes');
}

const hasPreferredRegions =
  Array.isArray(normalizedStudentProfile.regions_preferees) &&
  normalizedStudentProfile.regions_preferees.length > 0;

const acceptsNationalMobility =
  normalizedStudentProfile.mobilite_nationale === true;

if (!hasPreferredRegions && !acceptsNationalMobility) {
  deterministicMissingFields.push(
    'regions_preferees_ou_mobilite_nationale'
  );
}


// ============================================================
// 13. Fusionner les champs manquants sans doublons
// ============================================================

const finalMissingFields = [
  ...new Set([
    ...missingFieldsFromAgent,
    ...deterministicMissingFields
  ])
];

const profileComplete =
  agentStatus === 'complete' &&
  finalMissingFields.length === 0;


// ============================================================
// 14. Créer des questions de secours
// ============================================================

const fallbackQuestionMap = {
  bac_type:
    "Quel est ton type de baccalauréat ?",

  score:
    "Quel est ton score d'orientation ou ton score FG ?",

  domaines_preferes:
    "Quels domaines ou quelles filières souhaites-tu étudier ?",

  regions_preferees:
    "Dans quelles régions souhaites-tu étudier ?",

  regions_preferees_ou_mobilite_nationale:
    "Dans quelles régions souhaites-tu étudier, ou acceptes-tu d'étudier partout en Tunisie ?",

  mobilite_nationale:
    "Acceptes-tu d'étudier dans une autre région ?"
};

const finalQuestions = [...nextQuestions];

for (const missingField of finalMissingFields) {
  if (finalQuestions.length >= 3) {
    break;
  }

  const fallbackQuestion =
    fallbackQuestionMap[missingField];

  if (
    fallbackQuestion &&
    !finalQuestions.includes(fallbackQuestion)
  ) {
    finalQuestions.push(fallbackQuestion);
  }
}


// ============================================================
// 15. Créer une synthèse si le modèle ne l'a pas fournie
// ============================================================

function buildFallbackSummary(profile) {
  const parts = [];

  if (profile.bac_type) {
    parts.push(`bac ${profile.bac_type}`);
  }

  const availableScore =
    profile.score ?? profile.score_fg;

  if (availableScore !== null) {
    parts.push(`score ${availableScore}`);
  }

  if (profile.domaines_preferes.length > 0) {
    parts.push(
      `domaines souhaités : ${profile.domaines_preferes.join(', ')}`
    );
  }

  if (profile.regions_preferees.length > 0) {
    parts.push(
      `régions préférées : ${profile.regions_preferees.join(', ')}`
    );
  } else if (profile.mobilite_nationale === true) {
    parts.push('mobilité nationale acceptée');
  }

  if (parts.length === 0) {
    return 'Le profil étudiant est encore vide.';
  }

  return `Profil étudiant : ${parts.join('; ')}.`;
}

const profileSummary =
  ensureNullableString(result.profile_summary) ??
  buildFallbackSummary(normalizedStudentProfile);


// ============================================================
// 16. Gérer la mémoire des agents suivants
// ============================================================

// Dès que le profil change, les anciennes recherches et comparaisons
// ne doivent plus être considérées comme valides.

const searchResults = profileChanged
  ? {
      status: 'not_started',
      search_status: 'not_started',
      recommended_programs: [],
      excluded_programs: [],
      invalidated_reason: 'student_profile_changed'
    }
  : (
      state.search_results ?? {
        status: 'not_started',
        search_status: 'not_started',
        recommended_programs: [],
        excluded_programs: []
      }
    );

const comparisonResults = profileChanged
  ? {
      status: 'not_started',
      comparison_status: 'not_started',
      final_recommendations: [],
      invalidated_reason: 'student_profile_changed'
    }
  : (
      state.comparison_results ?? {
        status: 'not_started',
        comparison_status: 'not_started',
        final_recommendations: []
      }
    );


// ============================================================
// 17. Retourner l'état complet
// ============================================================

return {
  ...state,

  current_stage:
    profileComplete
      ? 'search'
      : 'profiling',

  student_profile:
    normalizedStudentProfile,

  profile_summary:
    profileSummary,

  profile_complete:
    profileComplete,

  profile_changed:
    profileChanged,

  changed_fields:
    changedFields,

  missing_fields:
    finalMissingFields,

  next_questions:
    finalQuestions.slice(0, 3),

  search_results:
    searchResults,

  comparison_results:
    comparisonResults,

  agent1_metadata: {
    parsed_successfully: true,
    reported_status:
      agentStatus || 'unknown',
    calculated_status:
      profileComplete
        ? 'complete'
        : 'incomplete',
    raw_content:
      content,
    parsed_at:
      new Date().toISOString()
  },

  updated_at:
    new Date().toISOString()
};

/*
 * Nœud : Préparer réponse profil incomplet
 * Mode : Run Once for Each Item
 *
 * Ce nœud :
 * 1. récupère les questions produites par Agent 1 ;
 * 2. élimine les doublons éventuels ;
 * 3. limite le nombre de questions à 3 ;
 * 4. génère une réponse lisible pour l'étudiant ;
 * 5. prépare les valeurs à sauvegarder.
 */

const state = $json;


// ============================================================
// 1. Normaliser les questions
// ============================================================

const rawQuestions = Array.isArray(state.next_questions)
  ? state.next_questions
  : [];

const questions = [
  ...new Set(
    rawQuestions
      .map(question => String(question).trim())
      .filter(Boolean)
  )
].slice(0, 3);


// ============================================================
// 2. Créer des questions de secours si nécessaire
// ============================================================

const fallbackQuestionMap = {
  bac_type:
    "Quel est ton type de baccalauréat ?",

  score:
    "Quel est ton score d'orientation ou ton score FG ?",

  score_fg:
    "Quel est ton score d'orientation ou ton score FG ?",

  domaines_preferes:
    "Quels domaines ou quelles filières souhaites-tu étudier ?",

  regions_preferees:
    "Dans quelles régions souhaites-tu étudier ?",

  regions_preferees_ou_mobilite_nationale:
    "Dans quelles régions souhaites-tu étudier, ou acceptes-tu d'étudier partout en Tunisie ?",

  mobilite_nationale:
    "Acceptes-tu d'étudier dans une autre région ?"
};

const missingFields = Array.isArray(state.missing_fields)
  ? state.missing_fields
  : [];

for (const field of missingFields) {
  if (questions.length >= 3) {
    break;
  }

  const fallbackQuestion = fallbackQuestionMap[field];

  if (
    fallbackQuestion &&
    !questions.includes(fallbackQuestion)
  ) {
    questions.push(fallbackQuestion);
  }
}


// ============================================================
// 3. Construire le message de réponse
// ============================================================

let output;

if (state.current_message.trim().toLowerCase() === "hey") {
  output =
    "Bonjour ! Je vais t'aider à identifier les formations universitaires " +
    "qui correspondent à ton profil.\n\n";
} else {
  output =
    "J'ai enregistré les informations de ton profil. " +
    "Pour continuer, j'ai besoin de quelques précisions.\n\n";
}

if (questions.length > 0) {
  output += questions
    .map((question, index) => `${index + 1}. ${question}`)
    .join("\n");
} else {
  output +=
    "Indique-moi ton type de bac, ton score, les domaines qui " +
    "t'intéressent et les régions dans lesquelles tu souhaites étudier.";
}


// ============================================================
// 4. Retourner l'état complet
// ============================================================

return {
  ...state,

  current_stage: "profiling",

  next_questions: questions,

  output,

  updated_at: new Date().toISOString(),

  memory_payload: {
    session_id: state.session_id,
    user_id: state.user_id,
    language: state.language,
    current_stage: "profiling",
    student_profile: JSON.stringify(
      state.student_profile
    ),
    search_results: JSON.stringify(
      state.search_results
    ),
    comparison_results: JSON.stringify(
      state.comparison_results
    ),
    updated_at: new Date().toISOString()
  }
};

/*
 * Nœud : Construire requête RAG
 * Mode : Run Once for Each Item
 *
 * Entrée :
 * Profil complet obtenu depuis Parser Agent 1.
 *
 * Sortie :
 * Une requête textuelle optimisée pour rechercher
 * des formations dans Pinecone.
 */

const state = $json;
const profile = state.student_profile ?? {};


// ============================================================
// 1. Fonctions utilitaires
// ============================================================

function cleanArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(item => String(item).trim())
    .filter(Boolean);
}

function displayList(value, fallback) {
  const items = cleanArray(value);

  return items.length > 0
    ? items.join(", ")
    : fallback;
}


// ============================================================
// 2. Récupérer les informations importantes
// ============================================================

const bacType =
  profile.bac_type ?? "non précisé";

const score =
  profile.score ??
  profile.score_fg ??
  "non précisé";

const domains = displayList(
  profile.domaines_preferes,
  "domaines compatibles avec le profil"
);

const regions = displayList(
  profile.regions_preferees,
  profile.mobilite_nationale === true
    ? "toutes les régions de Tunisie"
    : "région non précisée"
);

const preferredSubjects = displayList(
  profile.matieres_preferees,
  "non précisées"
);

const avoidedSubjects = displayList(
  profile.matieres_a_eviter,
  "aucune"
);

const institutionTypes = displayList(
  profile.types_etablissement,
  "tous les établissements publics compatibles"
);

const careerObjectives = displayList(
  profile.objectifs_professionnels,
  "objectifs professionnels non précisés"
);

const constraints = displayList(
  profile.contraintes,
  "aucune contrainte particulière"
);


// ============================================================
// 3. Construire la requête principale
// ============================================================

const searchQuery = [
  "Formations universitaires tunisiennes et choix d'orientation",
  `pour un étudiant titulaire d'un bac ${bacType}`,
  `avec un score d'orientation de ${score}.`,
  `Domaines et filières souhaités : ${domains}.`,
  `Régions préférées : ${regions}.`,
  `Types d'établissements : ${institutionTypes}.`,
  `Matières préférées : ${preferredSubjects}.`,
  `Matières à éviter : ${avoidedSubjects}.`,
  `Objectifs professionnels : ${careerObjectives}.`,
  `Contraintes : ${constraints}.`,
  "Rechercher les formations compatibles avec le type de bac,",
  "les codes de formation, les établissements, les universités,",
  "les gouvernorats, les conditions d'accès, les formules de calcul,",
  "les scores historiques, les capacités et les débouchés."
].join(" ");


// ============================================================
// 4. Construire plusieurs variantes de recherche
// ============================================================

const searchQueries = [
  {
    query_type: "exact_preferences",
    query: [
      `Formations en ${domains}`,
      `pour bac ${bacType}`,
      `score ${score}`,
      `dans ${regions}`
    ].join(", ")
  },
  {
    query_type: "bac_compatibility",
    query: [
      `Formations autorisées pour bac ${bacType}`,
      `score historique proche de ${score}`,
      `codes et établissements universitaires tunisiens`
    ].join(", ")
  },
  {
    query_type: "domain_search",
    query: [
      `Filières universitaires en ${domains}`,
      `débouchés et établissements`,
      `Tunisie`
    ].join(", ")
  },
  {
    query_type: "alternative_search",
    query: [
      `Alternatives proches de ${domains}`,
      `compatibles avec bac ${bacType}`,
      `score ${score}`
    ].join(", ")
  }
];


// ============================================================
// 5. Retourner l'état complet
// ============================================================

return {
  ...state,

  current_stage: "search",

  search_query: searchQuery,

  search_queries: searchQueries,

  search_context: {
    bac_type: bacType,
    student_score: score,
    preferred_domains: cleanArray(
      profile.domaines_preferes
    ),
    preferred_regions: cleanArray(
      profile.regions_preferees
    ),
    national_mobility:
      profile.mobilite_nationale === true,
    generated_at: new Date().toISOString()
  },

  updated_at: new Date().toISOString()
};

const profil =
$items("parse result")[0].json.profile;

const formations =
$items("extraire json")[0].json.formations;

return [{
  profil,
  formations
}];

let output = $json.output;

output = output
  .replace("```json", "")
  .replace("```", "")
  .trim();

return [{
  comparison_results: JSON.parse(output)
}];
